@use 'palette-tokens';

:root {
  color-scheme: light;
  --paper: #fff;
  --sidebar: #f7f7f6;
  // Activity rail and title bar. One step under the sidebar, same ink.
  --ground: #ececeb;
  --ink: #252932;
  --muted: #69717e;
  --line: #eceef1;
  --frame: #d0d4dd;
  --amber: #dda313;
  --mint: #237a43;
  --hover: #eeefef;
  --selection: var(--hover);
  --user: #f3f4f6;
  --code-head: #f8f8f9;
  --added: #eaf7ec;
  --removed: #fcecef;
  --danger: #b24c64;
  --sidebar-width: 238px;
  --header-height: 40px;
  --body-inset: 26px;
  --chat-width: 736px;
  // HeroUI owns --radius and its scale; keep application surfaces on that scale.
  --background: var(--paper);
  --foreground: var(--ink);
  --surface: var(--paper);
  --surface-foreground: var(--ink);
  --default: var(--hover);
  --accent: #2e3033;
  --accent-foreground: #fff;
  --accent-hover: color-mix(in srgb, var(--accent) 86%, var(--paper));
  --focus: #8195b3;
  --link: #3d6c99;
  --syntax-keyword: #af3767;
  --syntax-string: #9f4c67;
  --syntax-function: #4772ae;
  --status: #936b14;
  --border: var(--line);
  --chat-inline: var(--code-head);
  --chat-table-head: var(--code-head);
  --chat-line: var(--line);
  --chat-tool-fill: transparent;
  // Composer is a surface, the same idea as a HeroUI field: no stroke.
  // Light lifts a white well off the page with shadow. Dark uses a lighter fill.
  --composer-fill: var(--paper);
  --composer-fill-hover: var(--paper);
  --composer-control: var(--hover);
  --composer-control-hover: color-mix(in srgb, var(--ink) 10%, var(--hover));
  --composer-shadow:
    0 0 1px 0 rgb(0 0 0 / 6%), 0 1px 2px 0 rgb(0 0 0 / 4%), 0 6px 18px 0 rgb(0 0 0 / 4%);
  --composer-shadow-hover:
    0 0 1px 0 rgb(0 0 0 / 8%), 0 2px 4px 0 rgb(0 0 0 / 5%), 0 8px 20px 0 rgb(0 0 0 / 5%);
  font-family: -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Segoe UI', sans-serif;
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --paper: #202122;
  --sidebar: #1b1c1d;
  --ground: #121314;
  --ink: #e2e4e8;
  --muted: #a5adb9;
  --line: #303337;
  --frame: #494d55;
  --hover: #303236;
  --selection: var(--hover);
  --user: #2b2d30;
  --code-head: #27292c;
  --added: #203b2b;
  --removed: #41292f;
  --mint: #83c79a;
  --danger: #efa4b2;
  --accent: #e2e4e8;
  --accent-foreground: #202122;
  --link: #9cbae6;
  --syntax-keyword: #e898bd;
  --syntax-string: #e9a4b1;
  --syntax-function: #9cbae6;
  --status: #e1ba63;
  // Reading surfaces and interaction boundaries need different contrast steps.
  --chat-inline: color-mix(in srgb, var(--ink) 12%, var(--paper));
  --chat-table-head: color-mix(in srgb, var(--ink) 9%, var(--paper));
  --chat-line: color-mix(in srgb, var(--ink) 18%, var(--paper));
  --chat-tool-fill: color-mix(in srgb, var(--ink) 3%, var(--paper));
  --composer-fill: color-mix(in srgb, var(--ink) 9%, var(--paper));
  --composer-fill-hover: color-mix(in srgb, var(--ink) 12%, var(--paper));
  --composer-control: color-mix(in srgb, var(--ink) 10%, var(--composer-fill));
  --composer-control-hover: color-mix(in srgb, var(--ink) 16%, var(--composer-fill));
  --composer-shadow: 0 0 0 0 transparent;
  --composer-shadow-hover: 0 0 0 0 transparent;
}

@include palette-tokens.themes;

// Named palettes keep their published paper and sidebar.
// The shell is one step under that sidebar, so the rail does not fall back to ink.
:root[data-palette]:not([data-palette='ink']) {
  --ground: rgb(from var(--sidebar) calc(r - 11) calc(g - 11) calc(b - 11));
}
:root[data-theme='dark'][data-palette]:not([data-palette='ink']) {
  --ground: rgb(from var(--sidebar) calc(r - 9) calc(g - 9) calc(b - 9));
}

src/styles/_base.scss:
* {
  box-sizing: border-box;
}
/* Keep the window frame stationary; only content panes should scroll. */
html,
body,
#root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
}
body {
  margin: 0;
  background: #08090b;
  color: var(--ink);
  font:
    14px/1.55 -apple-system,
    BlinkMacSystemFont,
    'PingFang SC',
    'Segoe UI',
    sans-serif;
  -webkit-font-smoothing: antialiased;
}
/* Stop pane boundaries from forwarding trackpad gestures to the viewport. */
.conversation,
.projects,
.utility-view,
.model-options,
.search-results,
.tool-scroll,
.markdown-code-scroll,
.tool-text,
textarea {
  overscroll-behavior: none;
}
.code,
.markdown-code pre,
.reply-text table,
.table-scroll {
  overscroll-behavior-x: none;
}
::selection {
  background: #dda31338;
  color: var(--ink);
}
* {
  scrollbar-width: thin;
  scrollbar-color: #949ba64d transparent;
}
button,
textarea,
input {
  font: inherit;
  color: inherit;
}
textarea,
input {
  caret-color: var(--ink);
}
button {
  cursor: pointer;
}
button:disabled {
  cursor: default;
}
button:focus-visible,
[data-focus-visible='true'],
input:focus-visible,
textarea:focus-visible,
[tabindex='0']:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
svg {
  width: 17px;
  height: 17px;
  stroke-width: 1.5;
  flex: none;
}
.app-shell {
  margin: 28px;
  height: calc(100dvh - 56px);
  min-height: 480px;
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  grid-template-rows: var(--header-height) minmax(0, 1fr);
  background: var(--ground);
  border: 1px solid var(--frame);
  border-radius: var(--radius-4xl, calc(var(--radius) * 4));
  overflow: hidden;
}
.app-shell.native {
  margin: 0;
  height: 100dvh;
  border: 0;
  border-radius: 0;
}
.window-chrome {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: calc(48px + var(--sidebar-width)) minmax(0, 1fr);
  user-select: none;
  transition: grid-template-columns 280ms cubic-bezier(0.2, 0, 0, 1);
}
.app-shell[data-resizing='true'] .window-chrome,
.split-pane[data-resizing='true'] {
  transition: none;
}
.window-controls {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 0 16px;
  height: var(--header-height);
}
.window-chrome > .main-header {
  min-width: 0;
  border-bottom: 0;
  padding-right: 16px;
}
.sidebar-collapsed .window-chrome {
  grid-template-columns: 160px minmax(0, 1fr);
}
.workspace-surface {
  min-width: 0;
  min-height: 0;
  margin: 0 8px 8px 0;
  border: 1px solid var(--line);
  border-radius: var(--radius-2xl);
}

src/styles/_sidebar-layout.scss:
.sidebar-layout {
  grid-template-columns: minmax(0, 1fr);
  flex: 1;
  overflow: hidden;
  background: var(--paper);

  > :not(.split-pane-handle) {
    min-width: 0;
    min-height: 0;
  }

  &.has-sidebar > :first-child {
    background: var(--sidebar);
  }

  // The session list meets the conversation on this line only.
  &[data-split-active='true']:not([data-collapsible='true']) > :first-child {
    border-right: 1px solid var(--line);
  }
}

/* Peer library pages share their title row and compact HeroUI tools. */
.commands-browser-heading,
.package-library-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.commands-browser-title,
.package-library-title,
.utility-page-title {
  margin: 0;
  color: var(--ink);
  font-size: 16px;
  font-weight: 600;
  line-height: 24px;
}

.commands-tools,
.package-library-tools {
  display: flex;
  align-items: center;
  flex: none;
  gap: 2px;
}

.sidebar-layout .commands-tools .button.commands-tool-button,
.sidebar-layout .package-library-tools .button.package-tool-button {
  width: 28px;
  min-width: 28px;
  height: 28px;
  min-height: 28px;
  padding: 0;
  border: 0;
  color: var(--muted);
  background: transparent;

  &:is(:hover, [data-hovered='true'], [aria-expanded='true']) {
    color: var(--ink);
    background: var(--hover);
  }

  &:focus-visible {
    outline: 2px solid var(--focus);
    outline-offset: 2px;
  }

  svg {
    width: 14px;
    height: 14px;
  }
}

@media (max-width: 780px) {
  .sidebar-layout .commands-browser,
  .sidebar-layout .package-library {
    padding-top: 16px;
  }
}

src/styles/_appearance.scss:
// Miniatures use the very same palette tokens as the workbench.
.palette-preview {
  display: grid;
  grid-template-columns: 28% 1fr;
  height: 82px;
  overflow: hidden;
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}
.palette-preview-sidebar {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 13px 7px;
  background: var(--sidebar);
  border-right: 1px solid var(--line);
  i {
    height: 4px;
    border-radius: 2px;
    background: var(--muted);
    opacity: 0.65;
  }
  i:last-child {
    width: 60%;
  }
}
.palette-preview-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 9px;
  padding: 12px 10px 8px;
}
.palette-preview-text {
  width: 68%;
  height: 4px;
  border-radius: 2px;
  background: var(--ink);
  opacity: 0.45;
}
.palette-preview-code {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 14px;
  padding-inline: 5px;
  border-radius: 3px;
  background: var(--code-head);
  i {
    width: 24%;
    height: 3px;
    border-radius: 2px;
    background: var(--syntax-keyword);
  }
  i:nth-child(2) {
    width: 30%;
    background: var(--syntax-function);
  }
  i:nth-child(3) {
    width: 18%;
    background: var(--syntax-string);
  }
}
.palette-preview-composer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 15px;
  margin-top: auto;
  padding: 2px 3px 2px 5px;
  border: 1px solid var(--frame);
  border-radius: 4px;
  span {
    width: 40%;
    height: 2px;
    background: var(--muted);
    opacity: 0.5;
  }
  svg {
    width: 11px;
    height: 11px;
    padding: 2px;
    border-radius: 50%;
    background: var(--accent);
    color: var(--accent-foreground);
  }
}
.palette-preview-system {
  display: grid;
  grid-template-columns: 1fr 1fr;
  height: 82px;
  overflow: hidden;
  border-radius: var(--radius);
  .palette-preview {
    width: 100%;
    border-radius: 0;
  }
}
.settings-palette-row {
  margin-top: 10px;
}
.settings-palette-hint {
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.6;
}
.settings-palette-trigger {
  flex: none;
  gap: 9px;
  min-width: 206px;
  min-height: 36px;
  height: auto;
  padding: 7px 10px;
  border: 1px solid var(--settings-control-border);
  border-radius: var(--radius);
  background: var(--code-head);
  box-shadow: none;
  color: var(--ink);
  font-size: 13px;
  svg {
    width: 14px;
    height: 14px;
    margin-left: auto;
    color: var(--muted);
  }
}
.settings-palette-chip.palette-preview {
  display: block;
  width: 16px;
  height: 16px;
  flex: none;
  border-radius: 4px;
  border: 1px solid var(--frame);
  background: linear-gradient(90deg, var(--sidebar) 50%, var(--accent) 50%);
}
.settings-palette-popover {
  width: min(536px, calc(100vw - 32px));
  max-width: calc(100vw - 32px);
  padding: 0;
  border: 1px solid var(--frame);
  border-radius: var(--radius-xl);
  background: var(--paper);
  color: var(--ink);
  box-shadow: 0 12px 44px rgb(0 0 0 / 16%);
  .popover__dialog {
    display: flex;
    flex-direction: column;
    max-height: inherit;
    min-height: 0;
    padding: 16px;
  }
  .popover__heading {
    margin: 0 0 12px;
    font-size: 14px;
    font-weight: 600;
  }
}
.settings-palette-options {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
.settings-palette-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: minmax(108px, max-content);
  align-content: start;
  gap: 8px;
  max-height: min(480px, calc(100dvh - 120px));
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: 3px;
  overscroll-behavior: contain;
}
.settings-palette-option {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  min-width: 0;
  padding: 6px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  outline: none;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition:
    background-color 140ms ease,
    border-color 140ms ease,
    transform 100ms ease;
  .palette-preview {
    width: 100%;
    height: 64px;
    min-height: 64px;
    flex: none;
    border: 1px solid var(--line);
  }
  .palette-preview-sidebar {
    padding: 10px 5px;
    gap: 5px;
  }
  .palette-preview-main {
    gap: 5px;
    padding: 9px 7px 6px;
  }
  &[data-hovered='true'] {
    background: var(--hover);
  }
  &[data-selected='true'] {
    border-color: var(--ink);
    background: var(--code-head);
  }
  &[data-focus-visible='true'] {
    outline: 2px solid var(--focus);
    outline-offset: 1px;
  }
  &[data-pressed='true'] {
    transform: scale(0.98);
  }
}
.settings-palette-option-label {
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 20px;
  font-size: 13px;
  line-height: 1.4;
  svg {
    width: 13px;
    height: 13px;
    flex: none;
    margin-left: auto;
    visibility: hidden;
  }
  .settings-palette-option[data-selected='true'] & svg {
    visibility: visible;
  }
}
.settings-accent-row {
  padding-bottom: 20px;
}
.settings-accent-picker {
  flex: none;
  gap: 6px;
  .color-swatch-picker__item {
    width: 30px;
    height: 30px;
    border-radius: 50%;
  }
  .color-swatch-picker__swatch {
    border-radius: 50%;
  }
}
.settings-accent-default {
  margin-right: 7px;
  position: relative;
  .color-swatch-picker__swatch {
    display: block;
    height: 100%;
    background: var(--accent) !important;
  }
  &[data-selected='true'] {
    border-color: var(--ink);
  }
  .color-swatch-picker__indicator svg {
    color: var(--paper);
  }
  &::after {
    content: '';
    position: absolute;
    right: -9px;
    height: 18px;
    width: 1px;
    background: var(--line);
  }
}
@media (max-width: 640px) {
  .settings-palette-row,
  .settings-accent-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }
  .settings-palette-trigger {
    width: 100%;
  }
  .settings-accent-picker {
    flex-wrap: wrap;
  }
  .settings-palette-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (prefers-reduced-motion: reduce) {
  .settings-palette-option,
  .settings-theme-content {
    transition: none;
  }
}
